package com.metavirtuoso.conjunction.core.astro

import java.io.BufferedReader
import java.io.InputStreamReader

/**
 * Coefficient tables loaded once from the bundled Java resources
 * `com/metavirtuoso/conjunction/core/astro/ephemeris_tables.txt` and `delta_t.txt`
 * (generated by testdata/tools/make_ephemeris_tables.py and make_golden.py; the Swift engine
 * bundles the same two files byte-for-byte).
 */
internal object EphemerisData {
    /** One VSOP87 series: amplitudes A, phases B, frequencies C (term = A cos(B + C tau)). */
    class Series(val a: DoubleArray, val b: DoubleArray, val c: DoubleArray)

    /** VSOP87D series per body: index [variable 0=L,1=B,2=R][power]. */
    class Vsop(val series: Array<Array<Series>>)

    class MoonTables(val lr: Array<IntArray>, val b: Array<IntArray>)

    class DeltaT(val firstYear: Int, val seconds: DoubleArray)

    val vsop: Map<String, Vsop>
    val moon: MoonTables
    val pluto: Array<DoubleArray>
    val deltaT: DeltaT

    init {
        val lines = read("ephemeris_tables.txt")
        val vsopRaw = mutableMapOf<String, Array<MutableList<Series>>>()
        var moonLr: Array<IntArray>? = null
        var moonB: Array<IntArray>? = null
        var plutoRows: Array<DoubleArray>? = null
        var i = 0
        while (i < lines.size) {
            val header = lines[i++].trim()
            if (header.isEmpty() || header.startsWith("#")) continue
            val h = header.split(' ')
            when (h[0]) {
                "VSOP" -> {
                    val n = h[4].toInt()
                    val a = DoubleArray(n); val b = DoubleArray(n); val c = DoubleArray(n)
                    for (k in 0 until n) {
                        val p = lines[i++].trim().split(' ')
                        a[k] = p[0].toDouble(); b[k] = p[1].toDouble(); c[k] = p[2].toDouble()
                    }
                    val variable = when (h[2]) { "L" -> 0; "B" -> 1; "R" -> 2; else -> error("bad var ${h[2]}") }
                    val power = h[3].toInt()
                    val body = vsopRaw.getOrPut(h[1]) { Array(3) { mutableListOf() } }
                    val list = body[variable]
                    while (list.size <= power) list.add(Series(DoubleArray(0), DoubleArray(0), DoubleArray(0)))
                    list[power] = Series(a, b, c)
                }
                "MOON_LR" -> moonLr = Array(h[1].toInt()) { lines[i++].trim().split(' ').map(String::toInt).toIntArray() }
                "MOON_B" -> moonB = Array(h[1].toInt()) { lines[i++].trim().split(' ').map(String::toInt).toIntArray() }
                "PLUTO" -> plutoRows = Array(h[1].toInt()) { lines[i++].trim().split(' ').map(String::toDouble).toDoubleArray() }
                else -> error("Unknown section in ephemeris_tables.txt: $header")
            }
        }
        vsop = vsopRaw.mapValues { (_, vars) -> Vsop(Array(3) { vars[it].toTypedArray() }) }
        moon = MoonTables(checkNotNull(moonLr) { "MOON_LR missing" }, checkNotNull(moonB) { "MOON_B missing" })
        pluto = checkNotNull(plutoRows) { "PLUTO missing" }

        val rows = read("delta_t.txt").map { it.trim() }.filter { it.isNotEmpty() && !it.startsWith("#") }
            .map { it.split(' ') }
        deltaT = DeltaT(rows.first()[0].toInt(), rows.map { it[1].toDouble() }.toDoubleArray())
    }

    private fun read(name: String): List<String> {
        val stream = EphemerisData::class.java.getResourceAsStream(name)
            ?: error("Missing bundled resource $name")
        return BufferedReader(InputStreamReader(stream, Charsets.US_ASCII)).use { it.readLines() }
    }
}
